<?php $title = __('Salesman Price Difference — Issue Rate vs Selling'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="reports/price-difference"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><a class="btn btn-outline" href="<?= e(url('reports/price-difference', ['from' => $from, 'to' => $to, 'export' => 'csv'])) ?>"><?= __('CSV') ?></a><button class="btn btn-outline no-print" type="button" onclick="window.print()"><?= __('🖨 Print') ?></button></form>
<div class="cards">
  <div class="card red"><div class="lbl"><?= __('Below-Issue-Rate Loss') ?></div><div class="val"><?= money($loss) ?></div><div class="sub"><?= __('price sold below company issue rate') ?></div></div>
  <div class="card accent"><div class="lbl"><?= __('Above-Issue-Rate Margin') ?></div><div class="val"><?= money($gain) ?></div><div class="sub"><?= __('sold above issue rate') ?></div></div>
  <div class="card blue"><div class="lbl"><?= __('Net Difference') ?></div><div class="val"><?= money($gain - $loss) ?></div></div>
</div>
<div class="alert alert-info"><?= __('Rows where the salesman sold') ?><strong><?= __('below') ?></strong><?= __('the issue rate are marked red. Setting a product\'s') ?><strong><?= __('Minimum Selling Price') ?></strong><?= __('makes such sales require Owner/Admin approval.') ?></div>
<div class="panel print-area"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Invoice') ?></th><th><?= __('Date') ?></th><th><?= __('Customer') ?></th><th><?= __('Salesman') ?></th><th><?= __('Product') ?></th><th class="num"><?= __('Qty (Packets)') ?></th><th class="num"><?= __('Issue') ?></th><th class="num"><?= __('Selling') ?></th><th class="num"><?= __('Diff/Unit') ?></th><th class="num"><?= __('Difference') ?></th></tr></thead>
<tbody><?php foreach ($rows as $r): $d = (float)$r['difference']; ?>
<tr style="background:<?= $d > 0 ? '#fdf1ef' : 'inherit' ?>"><td class="mono"><?= e($r['invoice_no']) ?></td><td><?= date_display($r['date']) ?></td><td><?= e($r['customer']) ?></td><td><?= e($r['salesman'] ?? 'counter') ?></td><td><?= e($r['sku']) ?><br><span class="muted"><?= e($r['product']) ?></span></td><td class="num"><?= qty($r['qty']) ?></td><td class="num"><?= number_format($r['issue_rate'], 2) ?></td><td class="num"><?= number_format($r['selling_price'], 2) ?></td><td class="num"><?= number_format($r['issue_rate'] - $r['selling_price'], 2) ?></td><td class="num" style="color:<?= $d > 0 ? 'var(--red)' : 'var(--green)' ?>"><strong><?= ($d > 0 ? '−' : '+') . number_format(abs($d), 2) ?></strong></td></tr>
<?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="10" class="muted"><?= __('No sales with an issue rate in this period.') ?></td></tr><?php endif; ?></tbody></table></div></div>
